const { ref, inject, onMounted, nextTick } = Vue;

export default {
    setup() {
        const userInput = ref("");
        const contents = ref([
            {
                type: "system-response",
                content: "<b>你现在在一个神奇的房间里，输入WASD向对应方向移动。</b>"
            }
        ]);

        const backend = inject("backend");

        const checkReply = async () => {
            let inputValue = userInput.value;
            userInput.value = "";
            contents.value.push({
                type: "user-response",
                content: inputValue
            });
            await processBackend(inputValue);
        }

        const processBackend = async (text) => {
            let data;
            if (text) {
                data = await backend("c15-c15-6", {
                    text
                });
            } else {
                data = await backend("c15-c15-6", {});
            }

            if (data.reply) {
                contents.value.push({
                    type: "system-response",
                    content: data.reply
                });
            }
            contents.value.push({
                type: "system-response",
                content: data.roomResult
            });

            await scrollToBottom();
        }

        const scrollToBottom = async () => {
            await nextTick();
            let container = document.querySelector(".gameplay-scroll");
            container.scrollTop = container.scrollHeight;
        }

        onMounted(() => {
            processBackend();
        });

        return {
            userInput,
            contents,
            checkReply
        }
    }
}

